<template>
  <div><div class="toolbar page-toolbar"><strong class="cell-primary">Vai trò &amp; Quyền</strong><button class="button primary" @click="showForm = !showForm">{{ showForm ? 'Đóng biểu mẫu' : 'Tạo vai trò' }}</button></div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><section v-if="showForm" class="panel" style="margin-bottom:16px"><form class="inline-form" @submit.prevent="create"><div class="form-field"><label>Tên vai trò</label><input v-model.trim="form.name" class="form-input" required placeholder="CONTENT_EDITOR" /></div><div class="form-field"><label>Quyền (phân tách bằng dấu phẩy)</label><input v-model.trim="form.permissions" class="form-input" placeholder="academics.courses.read" /></div><button class="button primary" :disabled="busy">Tạo vai trò</button></form></section><section class="panel"><div class="panel-heading"><h2>Danh sách vai trò</h2><span>{{ roles.length }} vai trò</span></div><div v-if="loading" class="loading-state">Đang tải vai trò…</div><div v-else-if="roles.length" class="list-compact"><div v-for="role in roles" :key="role.id" class="list-compact-item"><div><strong>{{ role.name }}</strong><span>{{ role.permissions.join(' · ') || 'Chưa cấp quyền' }}</span></div><button class="mini-button" @click="remove(role)">Xóa</button></div></div><div v-else class="empty-state"><strong>Chưa có vai trò</strong><span>Vai trò hệ thống sẽ có sau khi khởi tạo.</span></div></section></div>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { identityApi } from '../../../shared/api/client'; const roles = ref<{ id: string; name: string; permissions: string[] }[]>([]); const loading = ref(true); const busy = ref(false); const showForm = ref(false); const error = ref(''); const form = reactive({ name: '', permissions: '' }); async function load() { loading.value = true; try { roles.value = await identityApi.roles() } catch (cause) { error.value = String((cause as Error)?.message || 'Không tải được vai trò.') } finally { loading.value = false } }; async function create() { busy.value = true; try { const role = await identityApi.createRole({ name: form.name, permissions: form.permissions.split(',').map(item => item.trim()).filter(Boolean) }); roles.value.push(role); form.name = ''; form.permissions = ''; showForm.value = false } catch (cause) { error.value = String((cause as Error)?.message || 'Không tạo được vai trò.') } finally { busy.value = false } }; async function remove(role: { id: string; name: string }) { if (!window.confirm(`Xóa vai trò ${role.name}?`)) return; try { await identityApi.deleteRole(role.id); roles.value = roles.value.filter(item => item.id !== role.id) } catch (cause) { error.value = String((cause as Error)?.message || 'Không xóa được vai trò.') } }; onMounted(load)
</script>
